-- ---- signal_snapshot (20 行) ----

ON CONFLICT DO NOTHING;

-- ---- identity 序列推进 ----
-- 上面的 INSERT 显式写入了 id，但 identity 序列不会因此前进；不 setval 的话
-- 下一次真实写入（storage/snapshots.py、monitor_targets.py 都不写 id）会撞主键。
-- 按目标表的 MAX(id)+1 计算，所以表里已有更大 id 时也安全。

DO $$
DECLARE seq text;
BEGIN
    seq := pg_get_serial_sequence('domain_config', 'id');
    IF seq IS NULL THEN
        RAISE EXCEPTION 'V11: domain_config.id 的 identity 序列不存在，setval 会静默失效';
    END IF;
    PERFORM setval(seq, COALESCE((SELECT MAX("id") FROM "domain_config"), 0) + 1, false);
END $$;

DO $$
DECLARE seq text;
BEGIN
    seq := pg_get_serial_sequence('fpr_table', 'id');
    IF seq IS NULL THEN
        RAISE EXCEPTION 'V11: fpr_table.id 的 identity 序列不存在，setval 会静默失效';
    END IF;
    PERFORM setval(seq, COALESCE((SELECT MAX("id") FROM "fpr_table"), 0) + 1, false);
END $$;

DO $$
DECLARE seq text;
BEGIN
    seq := pg_get_serial_sequence('signal_snapshot', 'id');
    IF seq IS NULL THEN
        RAISE EXCEPTION 'V11: signal_snapshot.id 的 identity 序列不存在，setval 会静默失效';
    END IF;
    PERFORM setval(seq, COALESCE((SELECT MAX("id") FROM "signal_snapshot"), 0) + 1, false);
END $$;
